install_like_cmds:
python3 - <<'EOF'
import json, glob, re
# Extract environment/pip installs and key model/doc references per notebook
for f in sorted(glob.glob('/tmp/rag_from_scratch_*.ipynb')):
    nb = json.load(open(f))
    print(f"===== {f.split('/')[-1]} =====")
    seen = set()
    for cell in nb['cells']:
        src = ''.join(cell['source'])
        if cell['cell_type'] == 'code':
            for m in re.finditer(r'!\s*pip install[^\n"]*|%\s*pip install[^\n"]*', src):
                line = m.group(0).strip()
                if line not in seen:
                    seen.add(line); print('  INSTALL:', line[:160])
        for m in re.finditer(r'https?://[^\s"\'\)\]\\]+', src):
            u = m.group(0)
            if any(k in u for k in ('http', '.pdf', '.txt', 'blog', 'arxiv', 'youtube')) and 'github.com/langchain' not in u and 'python.langchain' not in u and 'api.python' not in u and 'smith.langchain' not in u and 'openai.com' not in u and 'youtube.com/watch' not in u and 'youtu.be' not in u:
                if u not in seen and not u.startswith('https://python'):
                    seen.add(u); print('  URL:', u[:120])
    for m in re.finditer(r'(gpt-[a-z0-9.\-]+|text-embedding-[a-z0-9\-]+|llama[0-9.]*:?[\w]*|nomic-embed-text|mixtral|claude)', json.dumps(nb)):
        pass
    models = set(re.findall(r'(gpt-3\.5-turbo|gpt-4o(?:-mini)?|gpt-4|text-embedding-3-small|text-embedding-3-large|text-embedding-ada-002|llama3(?:\.1)?|nomic-embed-text|mixtral|phi3|gemma)', json.dumps(nb)))
    print('  MODELS:', ', '.join(sorted(models)))
EOF
